    location: 'Vijayanagar, Karnataka',
    latitude: 15.1394,
    longitude: 76.4108,
    industryType: 'Steel Manufacturing',
    claimed: 22000, 
    actual: 24000, 
    permit: 23000, 
    docVerified: true 
  }
];

const fraudAnalysis = industries.map(ind => {
  const discrepancy = Math.abs(ind.actual - ind.claimed);
  const discrepancyPct = (discrepancy / ind.actual * 100).toFixed(2);
  const overPermit = ind.actual - ind.permit;
  const violationPct = (overPermit / ind.permit * 100).toFixed(2);

  let fraudScore = 0;
  let flags = [];

  if (discrepancy > ind.actual * 0.1) { fraudScore += 30; flags.push('High discrepancy'); }
  if (overPermit > 0) { fraudScore += 40; flags.push('Exceeds permit'); }
  if (overPermit > ind.permit * 0.25) { fraudScore += 20; flags.push('Severe violation'); }
  if (!ind.docVerified && fraudScore > 0) { fraudScore += 10; flags.push('Documents not verified'); }

  return {
    companyName: ind.name,
    location: ind.location,
    latitude: ind.latitude,
    longitude: ind.longitude,
    industryType: ind.industryType,
    claimedEmissions: ind.claimed,
    detectedEmissions: ind.actual,
    permittedLimit: ind.permit,
    discrepancy: discrepancyPct + '%',
    overReleased: overPermit > 0 ? overPermit : 0,
    violationPercentage: overPermit > 0 ? violationPct : '0',
    fraudScore: Math.min(fraudScore, 100),
    status: fraudScore > 70 ? 'FRAUD_ALERT' : fraudScore > 40 ? 'VIOLATION' : 'COMPLIANT',
    riskLevel: fraudScore > 70 ? 'CRITICAL' : fraudScore > 40 ? 'HIGH' : 'LOW',
    requiresDocumentVerification: !ind.docVerified && fraudScore > 50,
    anomalies: flags.join('; '),
    timestamp: new Date().toISOString()
  };
});

const violations = fraudAnalysis.filter(f => f.status !== 'COMPLIANT');
const complianceRate = ((fraudAnalysis.length - violations.length) / fraudAnalysis.length * 100).toFixed(1);

return {
  fraudAnalysis,
  violations,
  summary: {
    totalIndustries: fraudAnalysis.length,
    violatingCount: violations.length,
    complianceRate: complianceRate + '%',
    totalOverEmission: violations.reduce((sum, v) => sum + v.overReleased, 0),
    criticalAlerts: fraudAnalysis.filter(f => f.status === 'FRAUD_ALERT').length,
    reportDate: new Date().toISOString()
  },
  reportGenerated: true
};

